import copy
import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def duplicate(source, target):
    if not exists(target) and not execute_tool('editor_toolset.toolsets.asset.AssetTools.duplicate', json.dumps({'path': source, 'new_path': target}))['returnValue']:
        raise RuntimeError('duplicate failed: ' + target)

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(obj, names):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': obj, 'properties': names}))['returnValue'])

def setv(obj, values):
    if not execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': obj, 'values': json.dumps(values)}))['returnValue']:
        raise RuntimeError('set failed: ' + str(obj))

def save(paths):
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('save failed')

def run():
    action = '/ExtractionOps/Input/IA_ExtractionInventory'
    duplicate('/ExtractionOps/Input/IA_ExtractionInteract', action)
    imc_path = '/ExtractionOps/Input/IMC_Extraction'
    imc = load(imc_path)
    mapping_struct = get(imc, ['defaultKeyMappings'])['defaultKeyMappings']
    mappings = mapping_struct['mappings']
    inventory_mappings = [m for m in mappings if 'IA_ExtractionInventory' in str(m.get('action'))]
    if not inventory_mappings:
        key_conflicts = [m for m in mappings if str(m.get('key')) == 'I']
        if key_conflicts:
            raise RuntimeError('I is already mapped: ' + str(key_conflicts))
        source = next((copy.deepcopy(m) for m in mappings if 'IA_ExtractionInteract' in str(m.get('action'))), None)
        if not source:
            raise RuntimeError('interact mapping template missing')
        source['action'] = {'refPath': action + '.IA_ExtractionInventory'}
        source['key'] = 'I'
        mappings.append(source)
        setv(imc, {'defaultKeyMappings': {'mappings': mappings}})
    addons_path = '/ExtractionOps/Input/DA_ExtractionInputAddOns'
    addons = load(addons_path)
    ability_actions = get(addons, ['abilityInputActions'])['abilityInputActions']
    if not any(a.get('inputTag', {}).get('tagName') == 'InputTag.Ability.Inventory' for a in ability_actions):
        ability_actions.append({'inputAction': {'refPath': action + '.IA_ExtractionInventory'}, 'inputTag': {'tagName': 'InputTag.Ability.Inventory'}})
        setv(addons, {'abilityInputActions': ability_actions})
    ability_set_path = '/ExtractionOps/AbilitySystem/AbilitySet_ExtractionCore'
    ability_set = load(ability_set_path)
    grants = get(ability_set, ['grantedGameplayAbilities'])['grantedGameplayAbilities']
    if not any('ExtractionGameplayAbility_ToggleInventory' in str(g.get('ability')) for g in grants):
        grants.append({'ability': {'refPath': '/Script/ExtractionOpsRuntime.ExtractionGameplayAbility_ToggleInventory'}, 'abilityLevel': 1, 'inputTag': {'tagName': 'InputTag.Ability.Inventory'}})
        setv(ability_set, {'grantedGameplayAbilities': grants})
    paths = [action, imc_path, addons_path, ability_set_path]
    save(paths)
    return {'action': action, 'key': 'I', 'inputTag': 'InputTag.Ability.Inventory', 'abilityGrantCount': len(grants)}
